package dev.awaken.body;

import org.jspecify.annotations.Nullable;

import java.util.List;

/**
 * The moves' full-body clips for players with the Player Animation Library (optional): generated by
 * tools/art/specs/body_moves.py into {@code assets/awaken/player_animations/body_moves.json}, each with a {@code _bent}
 * twin for Bendable Cuboids, and played through {@code core.api.PlayerClips} by the body client. Without the library
 * the body keeps its own vanilla-model poses. Common only so the GameTests can hold these names to the file.
 */
public final class BodyClips {
    private BodyClips() {}

    public static final String FILE = "assets/awaken/player_animations/body_moves.json";

    /** Held for the slide's length (a loop); then {@link #SLIDE_END} settles to standing, or {@link #SLIDE_JUMP} lifts out. */
    public static final String SLIDE = "body_slide", SLIDE_END = "body_slide_end", SLIDE_JUMP = "body_slide_jump";
    public static final String ROLL = "body_roll", MANTLE = "body_mantle";
    /** Looped while the tactical sprint lasts, then {@link #SPRINT_END}. */
    public static final String SPRINT = "body_sprint", SPRINT_END = "body_sprint_end";

    public static final List<String> ALL = List.of(SLIDE, SLIDE_END, SLIDE_JUMP, ROLL, MANTLE, SPRINT, SPRINT_END);

    /** The clip a move starts. */
    public static @Nullable String of(Move m) {
        return switch (m) {
            case SLIDE -> SLIDE;
            case ROLL -> ROLL;
            case MANTLE -> MANTLE;
            case TACTICAL_SPRINT -> SPRINT;
        };
    }

    /** Clips that run until the move ends (loops). */
    public static boolean held(Move m) {
        return m == Move.SLIDE || m == Move.TACTICAL_SPRINT;
    }
}
